def get_initial_board():
    return [list(row) for row in INITIAL_BOARD_STR]

def is_revealed(board):
    # Check if the top-right area is Sky Blue instead of Black
    # Cell (0, 37) is B in initial, S after LEFT
    if len(board) > 0 and len(board[0]) > 37:
        return board[0][37] == 'S'
    return False

def apply_reveal_transform(board):
    """Transforms the board from Hidden to Revealed state."""
    init = get_initial_board()

    # 1. Convert Top-Right BG (Rows 0-18, Cols 37-53) to S
    for r in range(0, 19):
        for c in range(37, 54):
            if r < len(board) and c < len(board[r]):
                board[r][c] = 'S'

    # 2. Transform Top-Left Zone (Rows 7-18, Cols 13-29)
    # Based on Trans 0 diff, this area gets populated with p, Y, W patterns

    # First, restore initial state for this zone to ensure clean base
    for r in range(7, 19):
        for c in range(13, 30):
             if r < len(board) and c < len(board[r]):
                 board[r][c] = init[r][c]

    # Apply Specific Pattern derived from Trans 0 observations
    # Rows 7-10: p at cols 14-16, 20-22, 26-28
    for r in range(7, 11):
        for c_base in [14, 20, 26]:
            for k in range(3):
                c = c_base + k
                if r < len(board) and c < len(board[r]):
                    board[r][c] = 'p'

    # Row 11: Y, W, Y at same cols
    r = 11
    for c_base in [14, 20, 26]:
        if r < len(board) and c_base < len(board[r]):
            board[r][c_base] = 'Y'
        if r < len(board) and c_base+1 < len(board[r]):
            board[r][c_base+1] = 'W'
        if r < len(board) and c_base+2 < len(board[r]):
            board[r][c_base+2] = 'Y'

    # Rows 13-18: Fill with S
    for r in range(13, 19):
        for c in range(13, 30):
             if r < len(board) and c < len(board[r]):
                 board[r][c] = 'S'

    # Handle specific single-cell changes observed in mismatches (Row 19, etc.)
    # The mismatch showed (19,13,B->S) etc. This suggests the reveal extends to Row 19?
    # Let's expand the S fill to Row 19 for Cols 13-29
    if len(board) > 19:
        for c in range(13, 30):
             if c < len(board[19]):
                 board[19][c] = 'S'
                 # Also extend to right side? (19,37,B->S)
                 for c_right in range(37, 54):
                     if c_right < len(board[19]):
                         board[19][c_right] = 'S'

def apply_hide_transform(board):
    """Transforms the board from Revealed to Hidden state (reverts reveal)."""
    init = get_initial_board()
    # Restore Top Half (Rows 0-19) to Initial
    for r in range(0, 20):
        for c in range(0, 64):
             if r < len(board) and c < len(board[r]):
                 board[r][c] = init[r][c]

def find_sprite_bounds(board):
    """Find bounding box of P, b, Y, W pixels."""
    min_r, max_r = 64, -1
    min_c, max_c = 64, -1

    # Search typical sprite region
    for r in range(36, 42):
        for c in range(15, 45):
            if board[r][c] in ['P', 'b', 'Y', 'W']:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if max_r == -1:
        return None

    return {'min_r': min_r, 'max_r': max_r, 'min_c': min_c, 'max_c': max_c}

def move_sprite(board, dc):
    """Move sprite horizontally by dc cells."""
    bounds = find_sprite_bounds(board)
    if not bounds:
        return board

    min_r, max_r = bounds['min_r'], bounds['max_r']
    min_c, max_c = bounds['min_c'], bounds['max_c']

    # Extract subgrid
    sub_grid = []
    for r in range(min_r, max_r + 1):
        row_data = []
        for c in range(min_c, max_c + 1):
            char = board[r][c]
            if char in ['P', 'b', 'Y', 'W']:
                row_data.append(char)
            else:
                row_data.append(None)
        sub_grid.append(row_data)

    # Clear old positions with 'S'
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if board[r][c] in ['P', 'b', 'Y', 'W']:
                board[r][c] = 'S'

    # Draw new positions
    for i, row_data in enumerate(sub_grid):
        nr = min_r + i
        for j, char in enumerate(row_data):
            if char is not None:
                nc = min_c + j + dc
                if 0 <= nr < 64 and 0 <= nc < 64:
                    board[nr][nc] = char

def update_status_bar(board):
    """Change first W to p in last row."""
    last_row_idx = len(board) - 1
    if last_row_idx >= 0:
        row = board[last_row_idx]
        for i in range(len(row)):
            if row[i] == 'W':
                row[i] = 'p'
                break

def handle_mouse_action(board, action):
    match = re.search(r'MOUSE\(row=(\d+),\s*col=(\d+)\)', action)
    if not match:
        return board
    mr, mc = int(match.group(1)), int(match.group(2))

    # Clear Green Zone if clicked near it
    if 25 <= mr <= 35 and 30 <= mc <= 55:
        for r in range(mr - 2, mr + 3):
            for c in range(mc - 2, mc + 3):
                if 0 <= r < 64 and 0 <= c < 64:
                    if board[r][c] in ['N', 'G', 'B']:
                        board[r][c] = 'S'

    # Clear Purple/Yellow Zone if clicked near it
    if 7 <= mr <= 18 and 13 <= mc <= 30:
         for r in range(mr - 2, mr + 3):
            for c in range(mc - 2, mc + 3):
                if 0 <= r < 64 and 0 <= c < 64:
                    if board[r][c] in ['p', 'Y', 'W']:
                        board[r][c] = 'S'

    update_status_bar(board)
    return board

def predict(board_lines, action):
    board = [list(line) for line in board_lines]

    if action == 'RESET':
        return ["".join(row) for row in get_initial_board()]

    revealed = is_revealed(board)

    if action == 'LEFT':
        if not revealed:
            # First Left: Reveal Map
            apply_reveal_transform(board)
        else:
            # Subsequent Left: Move Sprite Left
            move_sprite(board, -2)
        update_status_bar(board)

    elif action == 'RIGHT':
        if revealed:
            bounds = find_sprite_bounds(board)
            # Check if hitting right edge (approx col 41+)
            if bounds and bounds['max_c'] >= 41:
                apply_hide_transform(board)
            else:
                move_sprite(board, 2)
        else:
            # If hidden, Right moves sprite? 
            # Assuming standard movement applies even in hidden view if sprite exists
            move_sprite(board, 2)
        update_status_bar(board)

    elif action.startswith('MOUSE'):
        board = handle_mouse_action(board, action)

    else:
        # UP/DOWN etc - no change
        pass

    return ["".join(row) for row in board]

