            chars = [
                get_char(r, c), get_char(r, c+1),
                get_char(r+1, c), get_char(r+1, c+1)
            ]
            b_count = chars.count('b')
            s_count = chars.count('S')

            # Valid player candidates usually have mix of b and S
            if b_count > 0 and s_count > 0:
                # Prefer compact clusters over scattered ones
                score = b_count + s_count
                # Penalize if surrounded by walls G/B strictly? 
                # Just take the first valid or highest density
                if score > best_score:
                    best_score = score
