    # that might represent the player in different states.
    if player_pos is None:
        for r in range(ROWS - 1):
            for c in range(COLS - 1):
                if get_char(r, c) == 'b' and get_char(r, c+1) == 'S':
                    player_pos = (r, c)
                    break
            if player_pos: break

