    def get_background_color(r, c):
        # Check neighbors to guess floor type
        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < ROWS and 0 <= nc < COLS:
                ch = get_char(nr, nc)
                if ch in ['g', 'w', 'W', 'B']:
                    neighbors.append(ch)

        # Prioritize 'g' as it's the most common floor in corridors
        if 'g' in neighbors:
            return 'g'
        elif 'w' in neighbors:
            return 'w'
        elif 'W' in neighbors:
            return 'W'
        else:
            return 'B' # Default to black/wall if isolated

